"""
import json, os, sys, urllib.request
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

ENDPOINT = "https://api.typesafe.ai/v1/systemone"
PROMPT_CHARS = 500
QUESTIONS = {
    "acts": "The user asks the assistant to do, build, write, change, find or decide something. "
            "A bare acknowledgement, approval, or a number or letter picking an offered option does not count.",
    "solution": "The user hands the assistant a specific solution or exact steps to carry out.",
    "outcome": "The user names the outcome they want or the problem behind the request.",
    "invites": "The user invites options or recommendations, or asks what should be done.",
    "open": "There is more than one reasonable way to meet this request, so the assistant's own approach could matter.",
}


def api_key():
    key = os.environ.get("TYPESAFE_API_KEY", "").strip()
    if key:
        return key
    for line in (Path.home() / ".claude" / "typesafe.env").read_text().splitlines():
        name, _, value = line.strip().partition("=")
        if name.strip() == "TYPESAFE_API_KEY" and value.strip():
            return value.strip().strip("\"'")
    raise SystemExit("no TYPESAFE_API_KEY")


def ask(text, key):
    body = json.dumps({
        "state": {"user_request": text[:PROMPT_CHARS]},
        "model": "jev-latest",
        "questions": {k: {"type": "noul", "instructions": v} for k, v in QUESTIONS.items()},
    }).encode()
    req = urllib.request.Request(ENDPOINT, data=body, method="POST",
                                 headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=30) as r:
        answers = json.loads(r.read())["answers"]
    return {k: answers[k]["noul"] for k in QUESTIONS}


def bucket(s):
    # Uncertain band 0.30-0.70 per the capability map; thresholds owned here.
    if s["acts"] < 0.30:
        return "ack"
    if s["acts"] < 0.70:
        return "uncertain"
    goal = max(s["outcome"], s["invites"])
    if s["solution"] >= 0.70 and goal < 0.30:
        return "task"
    if goal >= 0.70 and s["solution"] < 0.70:
        return "goal"
    if s["solution"] >= 0.70 and goal >= 0.70:
        return "both"
    return "uncertain"


